class IntegerParseError(ValueError):
    pass

def parse_integer(text: str) -> int:
    try:
        return int(text)
    except ValueError as error:
        raise IntegerParseError("invalid integer") from error

checks.code:
try:
    parse_integer("bad")
except IntegerParseError as error:
    assert str(error) == "invalid integer"
else:
    raise AssertionError("failure was suppressed")

try:
    parse_integer("bad")
except IntegerParseError as error:
    assert isinstance(error.__cause__, ValueError)
else:
    raise AssertionError("failure was suppressed")

