def build_result(correlation_id: str, content: bytes) -> dict:
    text = content.decode("utf-8", errors="strict").replace("\r\n", "\n").replace("\r", "\n")
    if not text.strip():
        raise ValueError("blank document")
    return {"correlation_id": correlation_id, "text": text, "character_count": len(text), "line_count": len(text.splitlines()) or 1}

