class TextService:
    def __init__(self, reader) -> None:
        self._reader = reader

    def extract(self, content: bytes) -> str:
        text = self._reader.decode(content).replace("\r\n", "\n").replace("\r", "\n")
        if not text.strip():
            raise ValueError("blank document")
        return text

